export function matchRoles(text){ const lower=text.toLowerCase();return Object.entries(profiles).map(([id,p])=>({id,matched:p.terms.filter(t=>new RegExp(`\\b${t}\\b`,'i').test(lower))})).filter(x=>x.matched.length); }
